#!/usr/bin/env bash
# Rebuild the XRoboToolkit PC-Service .deb from the vendored source under
# vendor/XRoboToolkit-PC-Service/ with the Wuji patches baked into the binary.
#
# Vendor is self-contained: gRPC/abseil/protobuf/openssl static libs live in
# Redistributable/linux/. After `git lfs pull` this script needs no further
# network access.
#
# Requirements (Ubuntu 22.04):
#   sudo apt install build-essential cmake \
#       qt6-base-dev qt6-base-dev-tools qt6-5compat-dev qt6-declarative-dev \
#       dpkg-dev
#
# Typical run (from repo root):
#   cd src/input_devices/pico_input/vendor && ./build_pc_service.sh
#   sudo dpkg -i build/XRoboToolkit_PC_Service_*.deb
#
# Env overrides:
#   BUILD_NUM        Build number stamped into the binary  (default: 1)
#   QT6_PREFIX       Qt6 install prefix                    (default: auto-detect)

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROBOTICS_DIR="$SCRIPT_DIR/XRoboToolkit-PC-Service/RoboticsService"
REDIST_DIR="$ROBOTICS_DIR/Redistributable/linux"
OUTPUT_DIR="$SCRIPT_DIR/build"
BUILD_NUM="${BUILD_NUM:-1}"

if [ ! -d "$ROBOTICS_DIR" ]; then
    echo "ERROR: $ROBOTICS_DIR not found — vendor sources missing." >&2
    exit 1
fi

if [ ! -d "$REDIST_DIR/grpc/lib" ] || [ ! -f "$REDIST_DIR/grpc/lib/libgrpc.a" ]; then
    echo "ERROR: $REDIST_DIR/grpc/lib is missing or empty." >&2
    echo "       Run 'git lfs pull' from the repo root to fetch the static libs." >&2
    exit 1
fi

# Resolve Qt6 install prefix. Upstream qt-gcc.sh hardcodes /home/pico/Qt6/;
# we substitute the system Qt6 (or whatever the user set) without mutating
# the vendored script.
QT6_PREFIX="${QT6_PREFIX:-}"
if [ -z "$QT6_PREFIX" ]; then
    if pkg-config --exists Qt6Core 2>/dev/null; then
        QT6_PREFIX=$(pkg-config --variable=prefix Qt6Core)
    elif [ -d /usr/lib/x86_64-linux-gnu/cmake/Qt6 ]; then
        QT6_PREFIX=/usr
    else
        echo "ERROR: cannot locate Qt6. Install qt6-base-dev or set QT6_PREFIX." >&2
        exit 1
    fi
fi
echo "==> Using Qt6 prefix: $QT6_PREFIX"

DERIVED_BUILD="$ROBOTICS_DIR/qt-gcc-system.sh"
cat >"$DERIVED_BUILD" <<EOF
#!/bin/bash
# Generated by vendor/build_pc_service.sh — do not edit.
set -euo pipefail
DIR=\$(cd "\$(dirname "\${BASH_SOURCE[0]}")" && pwd)
cd \$DIR
RELEASE_DIR=\$DIR/RelWithDebInfo
mkdir -p bin "\$RELEASE_DIR"
if [ ! -f "\$RELEASE_DIR/CMakeCache.txt" ] || [ "\${1:-}" = "--clean" ]; then
    [ "\${1:-}" = "--clean" ] && rm -rf bin RelWithDebInfo && mkdir bin RelWithDebInfo
    cmake -S "\$DIR" -B "\$RELEASE_DIR" \\
        -DBUILD_LIB_PATH:STRING="$QT6_PREFIX" \\
        -DAUTO_BUILD_NUM:STRING="$BUILD_NUM" \\
        -DCMAKE_BUILD_TYPE:STRING=RelWithDebInfo \\
        -DCMAKE_PREFIX_PATH:PATH="$QT6_PREFIX"
fi
cmake --build "\$RELEASE_DIR" --target all -j\$(nproc)
EOF
chmod +x "$DERIVED_BUILD"

echo "==> Building PC-Service (build num=$BUILD_NUM)..."
"$DERIVED_BUILD"

PACK_DIR="$ROBOTICS_DIR/Package/debPack"
PACK_OUTPUT_DIR="$ROBOTICS_DIR/Package/output"
echo "==> Packaging .deb from $PACK_DIR..."
( cd "$PACK_DIR" && bash setup.sh )

mkdir -p "$OUTPUT_DIR"
# setup.sh copies the .deb to Package/output/ (sibling of debPack/).
DEB_PATH=$(find "$PACK_OUTPUT_DIR" "$PACK_DIR" -maxdepth 2 -name "*.deb" -newer "$DERIVED_BUILD" 2>/dev/null | head -1)
if [ -z "$DEB_PATH" ]; then
    echo "ERROR: no .deb produced. Check $PACK_DIR for build logs." >&2
    exit 1
fi
cp "$DEB_PATH" "$OUTPUT_DIR/"
echo "==> Built: $OUTPUT_DIR/$(basename "$DEB_PATH")"
echo "==> Install with: sudo dpkg -i $OUTPUT_DIR/$(basename "$DEB_PATH")"
